import { useState } from "react";
import C from "../constants/colors";
import { SHOPS_DATA } from "../constants/data";
import Card from "../components/ui/Card";
import Btn from "../components/ui/Btn";

function Shops() {
  const [search, setSearch] = useState("");
  const filtered = SHOPS_DATA.filter(s => s.name.toLowerCase().includes(search.toLowerCase()));

  const handleGetDirections = (shop) => {
    const query = encodeURIComponent(`${shop.name}, ${shop.address}`);
    const url = `https://www.google.com/maps/search/?api=1&query=${query}`;
    window.open(url, "_blank");
  };

  return (
    <div style={{ padding: 22 }}>
      <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: "0 0 4px" }}>🏪 Nearby Shops</h1>
      <p style={{ color: C.muted, fontSize: 13, margin: "0 0 14px" }}>Find agricultural shops, fertilizer dealers, and veterinary clinics near you</p>

      <input
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        placeholder="Search shops…"
        style={{
          width: "100%",
          maxWidth: 300,
          padding: "10px 12px",
          borderRadius: 8,
          border: `1px solid ${C.border}`,
          fontSize: 13,
          outline: "none",
          marginBottom: 14,
        }}
      />

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: 12 }}>
        {filtered.map((shop, i) => (
          <Card key={i} style={{ padding: "14px" }}>
            <div style={{ fontSize: 14, fontWeight: 600, color: C.text, marginBottom: 6 }}>
              {shop.name}
            </div>
            <div style={{ fontSize: 12, color: C.muted, marginBottom: 10, lineHeight: 1.5 }}>
              📍 {shop.address || "Address not available"}
              <br />
              📞 {shop.phone || "Phone not available"}
              <br />
              ⭐ {shop.rating || "N/A"} 
            </div>
            <Btn style={{ width: "100%", padding: "8px", fontSize: 12 }} onClick={() => handleGetDirections(shop)}>
              📍 Get Directions
            </Btn>
          </Card>
        ))}
      </div>
    </div>
  );
}

export default Shops;
